//! Typed counterparts of `axum::routing::{get, post, ...}`.
//!
//! Each takes the function generated by `#[air_tight::permission]` or
//! `#[air_tight::unrestricted]` (write `get(my_handler)` as with axum). A
//! plain axum handler does not compile here.

use axum::http::Method;

use crate::router::{MethodRouter, RouteTarget};

macro_rules! top_level {
    ($($name:ident => $method:ident),* $(,)?) => {$(
        #[doc = concat!("Routes `", stringify!($method), "` requests to a guarded or public handler.")]
        pub fn $name<F, R, T, S>(handler: F) -> MethodRouter<S>
        where
            F: FnOnce() -> R,
            R: RouteTarget<T, S>,
            T: 'static,
            S: Clone + Send + Sync + 'static,
        {
            MethodRouter::single(Method::$method, handler)
        }
    )*};
}

top_level!(
    get => GET,
    post => POST,
    put => PUT,
    patch => PATCH,
    delete => DELETE,
    head => HEAD,
    options => OPTIONS,
    trace => TRACE,
);
